//! Standalone workspace-topology checker (fgdb-g0-workspace-topology-1q9m).
//!
//! stdout is stable NDJSON; stderr is human diagnostics. Exit status is 0 for a
//! clean topology, 1 for violations, and 2 for usage/load failures.
//!
//! `--write` regenerates `docs/WORKSPACE_TOPOLOGY.md` from the registry.
//! Without it the committed document is compared against the regenerated bytes
//! and a difference is a violation: a generated artifact nobody regenerates is
//! a hand-edited artifact wearing a banner.

// Linked against the library rather than re-including its modules by `#[path]`,
// as `unsafe-ledger-check` already does. The `#[path]` form compiled a private
// second copy of `topology.rs`, which meant `topology` could not reference any
// module outside its own hand-listed set — and the checker it most needed to
// reach was `unsafe_ledger`, whose structural attribute scanner is the one
// reader for "does this source relax unsafe_code". That reachability limit is
// what kept a duplicate substring reader alive in `topology.rs`.
use registry_check::jsonl::{arr, b, event, n, s};
use registry_check::topology;
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use topology::{
    TopologyRegistry, Violation, check_source_blocks, generate_document, load_from_repo,
    load_topology, posture_closures, recompute_id_table_hash, recompute_semantic_contract_hash,
    required_edge_statuses, scan_workspace,
};

fn usage() -> String {
    "usage: topology-check [--root <repo-root>] [--registry <registry-path>] [--write]".into()
}

struct Args {
    root: PathBuf,
    registry: Option<PathBuf>,
    write: bool,
}

fn parse_args() -> Result<Args, String> {
    let mut arguments = std::env::args().skip(1);
    let mut root = None;
    let mut registry = None;
    let mut write = false;
    while let Some(argument) = arguments.next() {
        match argument.as_str() {
            "--root" => {
                if root.is_some() {
                    return Err(format!("--root may be provided only once\n{}", usage()));
                }
                root = Some(PathBuf::from(
                    arguments.next().ok_or("--root requires a value")?,
                ));
            }
            "--registry" => {
                if registry.is_some() {
                    return Err(format!("--registry may be provided only once\n{}", usage()));
                }
                registry = Some(PathBuf::from(
                    arguments.next().ok_or("--registry requires a value")?,
                ));
            }
            "--write" => write = true,
            "-h" | "--help" => return Err(usage()),
            other => return Err(format!("unknown argument {other:?}\n{}", usage())),
        }
    }
    Ok(Args {
        root: root.unwrap_or_else(|| PathBuf::from(".")),
        registry,
        write,
    })
}

fn emit_violation(violation: &Violation) {
    println!(
        "{}",
        event(&[
            ("event", s("topology_violation")),
            ("code", s(&violation.code)),
            ("subject", s(&violation.subject)),
            ("source_anchor", s(&violation.source_anchor)),
            ("replay_command", s(topology::REPLAY_COMMAND)),
            ("outcome", s("fail")),
            ("message", s(&violation.message)),
        ])
    );
    eprintln!(
        "violation[{}] {} {}: {}",
        violation.code, violation.subject, violation.source_anchor, violation.message
    );
}

fn emit_registry_event(registry: &TopologyRegistry, violations: usize, document_matches: bool) {
    println!(
        "{}",
        event(&[
            ("event", s("topology_registry_checked")),
            ("registry", s(&registry.registry.name)),
            ("layer_count", n(registry.layers.len() as i64)),
            ("crate_count", n(registry.crates.len() as i64)),
            (
                "active_crate_count",
                n(registry.active_crates().len() as i64)
            ),
            ("capability_count", n(registry.capabilities.len() as i64)),
            (
                "foundation_project_count",
                n(registry.foundation_projects.len() as i64)
            ),
            (
                "required_dependency_count",
                n(registry.required_dependencies.len() as i64)
            ),
            ("posture_count", n(registry.postures.len() as i64)),
            ("id_table_hash", s(recompute_id_table_hash(registry))),
            (
                "semantic_contract_hash",
                s(recompute_semantic_contract_hash(registry))
            ),
            ("document_matches", b(document_matches)),
            ("violations", n(violations as i64)),
            ("outcome", s(if violations == 0 { "pass" } else { "fail" })),
        ])
    );
}

fn emit_source_blocks(registry: &TopologyRegistry, root: &Path) {
    let mut ids: Vec<String> = registry
        .source_blocks
        .iter()
        .map(|block| block.id.clone())
        .collect();
    ids.sort();
    for (id, result) in ids.into_iter().zip(check_source_blocks(registry, root)) {
        match result {
            Ok(check) => println!(
                "{}",
                event(&[
                    ("event", s("source_block_checked")),
                    ("source_block", s(check.id)),
                    ("line_count", n(check.line_count as i64)),
                    ("byte_count", n(check.byte_count as i64)),
                    ("fnv1a64", s(check.fnv1a64)),
                    ("outcome", s(check.outcome)),
                ])
            ),
            Err(message) => println!(
                "{}",
                event(&[
                    ("event", s("source_block_checked")),
                    ("source_block", s(id)),
                    ("line_count", n(0)),
                    ("byte_count", n(0)),
                    ("fnv1a64", s("")),
                    ("outcome", s("fail")),
                    ("message", s(message)),
                ])
            ),
        }
    }
}

/// One event per crate row — the bead's structured-logging contract. Emitted
/// for planned crates too: a map is only useful if the unbuilt part is legible.
fn emit_crates(registry: &TopologyRegistry, root: &Path) {
    let scan = scan_workspace(root).ok();
    for row in &registry.crates {
        let scanned = scan
            .as_ref()
            .and_then(|scan| scan.by_dir(&row.manifest_dir));
        let resolved: Vec<String> = scanned
            .map(|entry| {
                entry
                    .dependencies
                    .iter()
                    .map(|dependency| format!("{}:{}", dependency.table, dependency.package))
                    .collect()
            })
            .unwrap_or_default();
        let layer = registry.layer(&row.layer);
        println!(
            "{}",
            event(&[
                ("event", s("crate_checked")),
                ("event_version", n(1)),
                ("crate", s(&row.name)),
                ("layer", s(&row.layer)),
                (
                    "layer_order",
                    n(layer.map(|l| l.source_order as i64).unwrap_or(0))
                ),
                ("activation_status", s(&row.activation_status)),
                ("unsafe_policy", s(&row.unsafe_policy)),
                ("posture_participation", s(&row.posture_participation)),
                ("owner", s(&row.owner)),
                ("owner_bead", s(&row.owner_bead)),
                ("resolved_dependencies", arr(resolved)),
                (
                    "allowed_edges",
                    arr(layer
                        .map(|l| l.allowed_outgoing_layers.clone())
                        .unwrap_or_default())
                ),
                (
                    "root_forbids_unsafe",
                    b(scanned
                        .map(|entry| entry.root_forbids_unsafe)
                        .unwrap_or(false))
                ),
                ("replay_command", s(topology::REPLAY_COMMAND)),
                ("outcome", s("pass")),
            ])
        );
    }
}

/// One event per inventory row — "built here" and "consumed from" are the two
/// halves of the same closed-universe claim, so they share a schema.
fn emit_inventory(registry: &TopologyRegistry) {
    for capability in &registry.capabilities {
        println!(
            "{}",
            event(&[
                ("event", s("capability_checked")),
                ("event_version", n(1)),
                ("capability", s(&capability.id)),
                ("disposition", s(&capability.disposition)),
                ("owner_crate", s(&capability.owner_crate)),
                ("foundation_project", s(&capability.foundation_project)),
                ("foundation_asset", s(&capability.foundation_asset)),
                ("source_phrase", s(&capability.source_phrase)),
                ("outcome", s("pass")),
            ])
        );
    }
}

fn emit_edges_and_postures(registry: &TopologyRegistry, root: &Path) {
    let Ok(scan) = scan_workspace(root) else {
        return;
    };
    let statuses = required_edge_statuses(registry, &scan);
    let live = statuses
        .iter()
        .filter(|status| status.status != "deferred")
        .count();
    for status in &statuses {
        println!(
            "{}",
            event(&[
                ("event", s("required_edge_checked")),
                ("edge", s(&status.id)),
                ("detail", s(&status.detail)),
                (
                    "outcome",
                    s(match status.status {
                        "pass" => "pass",
                        "fail" => "fail",
                        other => other,
                    })
                ),
            ])
        );
    }
    println!(
        "{}",
        event(&[
            ("event", s("required_edge_coverage")),
            ("declared", n(statuses.len() as i64)),
            ("evaluated_live", n(live as i64)),
            ("deferred", n((statuses.len().saturating_sub(live)) as i64)),
            ("outcome", s("pass")),
        ])
    );
    for closure in posture_closures(registry, &scan) {
        println!(
            "{}",
            event(&[
                ("event", s("posture_closure_checked")),
                ("posture", s(&closure.posture_id)),
                ("entry_crate", s(&closure.entry_crate)),
                ("closure", arr(closure.closure.clone())),
                ("illegal", arr(closure.illegal.clone())),
                (
                    "outcome",
                    s(if closure.status == "deferred" {
                        "deferred"
                    } else if closure.illegal.is_empty() {
                        "pass"
                    } else {
                        "fail"
                    })
                ),
            ])
        );
    }
    println!(
        "{}",
        event(&[
            ("event", s("workspace_scanned")),
            ("members", arr(scan.members.clone())),
            ("workspace_unsafe_lint", s(&scan.workspace_unsafe_lint)),
            ("toolchain_channel", s(&scan.toolchain_channel)),
            ("outcome", s("pass")),
        ])
    );
}

fn run(root: &Path, registry_path: Option<&Path>, write: bool) -> Result<usize, String> {
    let registry = match registry_path {
        Some(path) if path.is_absolute() => load_topology(path),
        Some(path) => load_topology(&root.join(path)),
        None => load_from_repo(root),
    }
    .map_err(|error| error.to_string())?;

    let mut violations = topology::validate_topology(&registry, root);
    let generated = generate_document(&registry, root)?;

    let document_path = root.join(&registry.registry.document_path);
    if write {
        std::fs::write(&document_path, generated.as_bytes())
            .map_err(|error| format!("{}: {error}", document_path.display()))?;
        eprintln!("wrote {}", document_path.display());
    }
    let committed = std::fs::read_to_string(&document_path).unwrap_or_default();
    let document_matches = committed == generated;
    if !document_matches {
        violations.push(Violation {
            code: "document_drift".into(),
            subject: registry.registry.document_path.clone(),
            source_anchor: "§19 G0".into(),
            message: format!(
                "the committed document differs from the regenerated bytes; run `{} --write`",
                topology::REPLAY_COMMAND
            ),
        });
    }

    emit_registry_event(&registry, violations.len(), document_matches);
    emit_source_blocks(&registry, root);
    emit_crates(&registry, root);
    emit_inventory(&registry);
    emit_edges_and_postures(&registry, root);
    for violation in &violations {
        emit_violation(violation);
    }
    Ok(violations.len())
}

fn main() -> ExitCode {
    let args = match parse_args() {
        Ok(args) => args,
        Err(error) => {
            eprintln!("{error}");
            return ExitCode::from(2);
        }
    };
    match run(&args.root, args.registry.as_deref(), args.write) {
        Ok(0) => ExitCode::SUCCESS,
        Ok(_) => ExitCode::from(1),
        Err(error) => {
            println!(
                "{}",
                event(&[
                    ("event", s("topology_load_error")),
                    ("root", s(args.root.display().to_string())),
                    ("outcome", s("load_error")),
                    ("message", s(&error)),
                ])
            );
            eprintln!("topology-check load error: {error}");
            ExitCode::from(2)
        }
    }
}
